+                if ( file_type_id >= 0 )
+                    H5Tclose(file_type_id);
+                if ( file_space_id >= 0 )
+                    H5Sclose(file_space_id);
+                H5Dclose(dset_id);
+                break;
+            }
+
+            {
+                hsize_t file_nelems = H5Sget_simple_extent_npoints(file_space_id);
+                size_t file_type_size = H5Tget_size(file_type_id);
+
+                if ( file_nelems != (hsize_t)nelems || file_type_size != (size_t)matvar->data_size ) {
+                    H5Sclose(file_space_id);
+                    H5Tclose(file_type_id);
+                    H5Dclose(dset_id);
+                    break;
+                }
+
+                if ( MAT_C_CHAR == matvar->class_type &&
+                     !(H5Tequal(file_type_id, H5T_NATIVE_UCHAR) > 0 ||
+                       H5Tequal(file_type_id, H5T_STD_U8LE) > 0 ||
+                       H5Tequal(file_type_id, H5T_STD_U8BE) > 0) ) {
+                    H5Sclose(file_space_id);
+                    H5Tclose(file_type_id);
+                    H5Dclose(dset_id);
+                    break;
+                }
+            }
+
             if ( !matvar->isComplex ) {
                 matvar->data = malloc(matvar->nbytes);
             } else {
@@ -1246,6 +1280,8 @@
                 err = Mat_H5ReadData(dset_id, data_type_id,
                     H5S_ALL, H5S_ALL, matvar->isComplex, matvar->data);
             }
+            H5Sclose(file_space_id);
+            H5Tclose(file_type_id);
             H5Dclose(dset_id);
             break;
         }

